import {toCents,formatMoney,monthSummary,categorySpend,splitBill,balances,settlements,validateImport} from './finance.js';
const $=selector=>document.querySelector(selector), KEY='numiz-budget-buddy-v1';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PATHS={home:'M3 10 12 3l9 7v10h-6v-7H9v7H3Z',wallet:'M3 6h16v15H3z M3 6l14-4v4 M15 12h6v5h-6z',transactions:'M4 7h15 m-4-4 4 4-4 4 M20 17H5 m4-4-4 4 4 4',chart:'M4 21V10h4v11 M10 21V3h4v18 M16 21v-8h4v8',goal:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',split:'M8 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M16 4a3 3 0 1 0 2 6 M2 21v-3a6 6 0 0 1 12 0v3 M16 14a6 6 0 0 1 6 6',settings:'m9 3-.5 3-2 1-2.5-1-2 3 2 2v2l-2 2 2 3 2.5-1 2 1 .5 3h4l.5-3 2-1 2.5 1 2-3-2-2v-2l2-2-2-3-2.5 1-2-1-.5-3Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',plus:'M12 5v14 M5 12h14',arrow:'M4 12h16 m-5-5 5 5-5 5',down:'m6 9 6 6 6-6',up:'m7 14 5-5 5 5 M12 9v12',income:'m7 10 5 5 5-5 M12 3v12',expense:'m7 8 5-5 5 5 M12 3v12',user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0 M4 21v-3a8 8 0 0 1 16 0v3',close:'m6 6 12 12 M18 6 6 18',check:'m5 12 4 4L19 6',more:'M5 12h.01 M12 12h.01 M19 12h.01',search:'m21 21-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',info:'M12 11v6 M12 7h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',food:'M5 3v7a3 3 0 0 0 6 0V3 M8 3v18 M17 3v18 M17 3c-5 4-5 10 0 10',bag:'M4 7h16l1 14H3z M8 8V6a4 4 0 0 1 8 0v2',transport:'M5 4h14v13H5z M5 12h14 M8 17v3 M16 17v3 M8 14h.01 M16 14h.01',bills:'M5 2h14v20l-3-2-4 2-4-2-3 2z M8 7h8 M8 11h8 M8 15h5',health:'M10 3h4v7h7v4h-7v7h-4v-7H3v-4h7z',fun:'M4 7h16v13H4z M8 7V4h8v3 M8 12v3 M16 12v3 M8 17h8',education:'m2 8 10-5 10 5-10 5Z M6 10v7c4 4 8 4 12 0v-7 M22 8v9',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',plane:'m2 16 8-5V4c0-3 4-3 4 0v7l8 5v3l-8-2v4l-2 2-2-2v-4l-8 2Z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${PATHS[name]||PATHS.wallet}"/></svg>`;
const EXPENSE_CATEGORIES=['Food & dining','Groceries','Transport','Shopping','Bills & utilities','Health','Entertainment','Education','Other'];
const INCOME_CATEGORIES=['Salary','Freelance','Gift','Other'];
const CURRENCIES=['USD','EUR','GBP','INR','AED','CAD','AUD'];
const COLORS=['#31594c','#bcd69b','#cec8ed','#e9c8b3','#a9bfbc','#ddd8a0'];
const categoryIcon=c=>({'Food & dining':'food','Groceries':'bag','Transport':'transport','Shopping':'bag','Bills & utilities':'bills','Health':'health','Entertainment':'fun','Education':'education','Salary':'wallet','Freelance':'wallet','Gift':'spark'}[c]||'wallet');
const localDate=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const currentMonth=()=>localDate().slice(0,7);
const id=()=>crypto.randomUUID();
const decimal=cents=>`${Math.floor(cents/100)}.${String(cents%100).padStart(2,'0')}`;
function futureDate(days){const d=new Date();d.setDate(d.getDate()+days);return localDate(d);}
function freshState(demo=false,currency='USD',profile='Individual'){
 const state={version:1,demo,currency,profile,transactions:[],budgets:[],goals:[],participants:[],bills:[]};if(!demo)return state;
 const month=currentMonth(),day=new Date().getDate(),date=d=>`${month}-${String(Math.min(d,day)).padStart(2,'0')}`;
 const entries=[['income','Monthly salary',420000,'Salary',1],['income','Design project',65000,'Freelance',10],['expense','Fresh market',8450,'Groceries',2],['expense','Morning coffee',650,'Food & dining',3],['expense','Weekend dinner',5840,'Food & dining',5],['expense','Monthly rent',120000,'Bills & utilities',1],['expense','Train pass',7500,'Transport',4],['expense','A little something',4290,'Shopping',8],['expense','Movie night',2400,'Entertainment',12],['expense','Weekly groceries',6200,'Groceries',14],['expense','Internet bill',4500,'Bills & utilities',6],['expense','Lunch with friends',3250,'Food & dining',17]];
 state.transactions=entries.map(([type,name,amountCents,category,d])=>({id:id(),type,name,amountCents,category,date:date(d)}));
 state.budgets=[['Food & dining',22000],['Groceries',28000],['Transport',15000],['Shopping',18000],['Bills & utilities',150000],['Entertainment',10000]].map(([category,limitCents])=>({id:id(),category,limitCents}));
 state.goals=[{id:id(),name:'A little getaway',targetCents:200000,savedCents:128000,targetDate:futureDate(100),color:COLORS[1]},{id:id(),name:'Rainy day fund',targetCents:500000,savedCents:185000,targetDate:futureDate(220),color:COLORS[2]}];
 state.participants=[{id:'you',name:'You'},{id:'alex',name:'Alex'},{id:'sam',name:'Sam'}];state.bills=[{id:id(),title:'Weekend groceries',amountCents:8450,paidBy:'you',participants:['you','alex','sam'],date:date(8)},{id:id(),title:'Friday dinner',amountCents:6000,paidBy:'alex',participants:['you','alex','sam'],date:date(10)}];return state;
}
let state;try{const saved=localStorage.getItem(KEY);state=saved?validateImport(JSON.parse(saved)):freshState(true);}catch{state=freshState(true);}
let page=location.hash.slice(1)||'overview',month=currentMonth(),search='',typeFilter='all',categoryFilter='All',sort='newest',toastTimer,undoAction,storageFailed=false;
const money=cents=>formatMoney(cents,state.currency);
function clearUndo(){undoAction=null;clearTimeout(toastTimer);$('#toast').classList.remove('visible');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;return true;}catch{storageFailed=true;return false;}}
function toast(message,undo=null){clearTimeout(toastTimer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?8500:4500);}
const nameOf=personId=>state.participants.find(p=>p.id===personId)?.name||'Former member';
const shortDate=date=>date?new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No deadline';
const monthTitle=()=>new Date(`${month}-01T12:00:00`).toLocaleDateString(undefined,{month:'long',year:'numeric'});
function navItems(){return [['overview','home','Overview'],['transactions','transactions','Transactions'],['budgets','chart','Budgets'],['savings','goal','Savings goals'],['split','split','Split bills']];}
function shell(){const nav=navItems();$('#sidebar').innerHTML=`<a href="#overview" class="brand"><img src="assets/icon.svg" alt="">numiz<span class="dot">.</span></a><div class="brand-sub">YOUR BUDGET BUDDY</div><div class="nav-label">YOUR MONEY, SIMPLIFIED</div><nav class="side-nav" aria-label="Main navigation">${nav.map(([key,i,label])=>`<a class="nav-link ${key===page?'active':''}" href="#${key}" ${key===page?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}</nav><div class="side-divider"></div><a class="nav-link ${page==='settings'?'active':''}" href="#settings">${icon('settings')}Preferences</a><div class="sidebar-bottom"><svg class="side-art" viewBox="0 0 100 80"><path d="M14 62h72 M22 61V42h14v19 M43 61V29h14v32 M64 61V15h14v46" stroke="#638774"/><path d="m19 29 25-11 18 3L81 5 m-8 0h8v8" stroke="#bedc9c"/></svg><h3>Small steps.<br>Brighter possibilities.</h3><p>A little clarity today.<br>A little more freedom tomorrow.</p><button class="btn btn-outline" data-action="fresh">${icon('spark')}Start my own budget</button></div><div class="version">BUILT AROUND YOUR EVERYDAY</div>`;$('#topbar').innerHTML=`<div class="eyebrow">A little clarity goes a long way.</div><a href="#overview" class="brand mobile-brand"><img src="assets/icon.svg" alt="">numiz<span class="dot">.</span></a><div class="top-right"><span class="today">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><button class="profile" data-action="settings" aria-label="Open preferences"><span class="avatar">${icon('user')}</span><span class="profile-text">${esc(state.profile)} workspace</span>${icon('down')}</button></div>`;$('#mobile-nav').innerHTML=nav.map(([key,i,label])=>`<a class="mobile-link ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(i)}${key==='overview'?'Home':key==='transactions'?'Activity':key==='savings'?'Goals':key==='split'?'Split':label}</a>`).join('');}
function heading(title,subtitle,action='transaction',actionLabel='Add transaction',monthPicker=false){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${monthPicker?`<input type="month" id="month-picker" class="select month-select" aria-label="Reporting month" value="${month}" min="2000-01" max="2100-12">`:''}${action?`<button class="btn btn-primary" data-action="${action}">${icon('plus')}${actionLabel}</button>`:''}</div></div>`;}
function demoBar(){return state.demo?`<div class="demo-bar"><span>${icon('info')}You’re exploring a sample budget. All numbers are examples.</span><button data-action="fresh">Start my own ${'→'}</button></div>`:'';}
function empty(title,message,action='transaction',label='Add a transaction',i='wallet'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${message}</p>${action?`<button class="btn btn-primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function summaryCards(){const s=monthSummary(state.transactions,month);return `<section class="summary-grid" aria-label="Monthly summary"><article class="summary-card primary"><div class="summary-label">This month’s balance</div><div class="summary-number">${money(s.balance)}</div><div class="summary-note">${icon('spark')}A little more clarity, one day at a time.</div></article><article class="summary-card"><span class="summary-icon">${icon('income')}</span><div class="summary-label">Money in</div><div class="summary-number">${money(s.income)}</div><div class="summary-note">Recorded income · ${esc(monthTitle())}</div></article><article class="summary-card"><span class="summary-icon peach">${icon('expense')}</span><div class="summary-label">Money out</div><div class="summary-number">${money(s.expenses)}</div><div class="summary-note">Recorded expenses · ${esc(monthTitle())}</div></article></section>`;}
function trendChart(){const count=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();const tx=state.transactions.filter(t=>t.date.startsWith(month));if(!tx.length)return '<div class="chart-empty">A clear picture starts with one entry.<br>Add a transaction to see your monthly money flow.</div>';const income=Array(count).fill(0),expense=Array(count).fill(0);for(const t of tx)(t.type==='income'?income:expense)[Number(t.date.slice(8,10))-1]+=t.amountCents;for(let i=1;i<count;i++){income[i]+=income[i-1];expense[i]+=expense[i-1];}const max=Math.max(...income,...expense,100),y=v=>159-v/max*137,x=i=>34+i/(count-1)*415;const path=arr=>arr.map((n,i)=>`${i?'L':'M'}${x(i).toFixed(2)} ${y(n).toFixed(2)}`).join(' ');return `<svg viewBox="0 0 470 188" role="img" aria-label="Cumulative monthly income ${esc(money(income.at(-1)))} and expenses ${esc(money(expense.at(-1)))}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b5cf9e" stop-opacity=".21"/><stop offset="100%" stop-color="#b5cf9e" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(n=>{const yy=22+n*137/3;return `<line x1="34" x2="449" y1="${yy}" y2="${yy}" stroke="#edf1e6" stroke-width="1" stroke-dasharray="3 5"/><text x="0" y="${yy+3}">${Math.round(max*(1-n/3)/100).toLocaleString()}</text>`;}).join('')}<path d="${path(income)} L449 159 L34 159Z" fill="url(#chart-fill)"/><path d="${path(income)}" stroke="#b1cb94" stroke-width="2.5" stroke-linejoin="round"/><path d="${path(expense)}" stroke="#31594c" stroke-width="2.5" stroke-linejoin="round"/>${[0,Math.floor(count/4),Math.floor(count/2),Math.floor(count*3/4),count-1].map(i=>`<text x="${x(i)}" y="181" text-anchor="middle">${i+1} ${new Date(`${month}-01T12:00:00`).toLocaleDateString(undefined,{month:'short'})}</text>`).join('')}</svg>`;}
function spendingChart(){const categories=Object.entries(categorySpend(state.transactions,month)).sort((a,b)=>b[1]-a[1]),total=categories.reduce((s,[,v])=>s+v,0);if(!total)return '<div class="chart-empty">No spending recorded this month.<br>Your category breakdown will appear here.</div>';const data=categories.length>5?[...categories.slice(0,4),['Other categories',categories.slice(4).reduce((s,[,v])=>s+v,0)]]:categories;let offset=0;return `<div class="donut-layout"><div class="donut-wrap"><svg viewBox="0 0 148 148" role="img" aria-label="Spending by category"><circle cx="74" cy="74" r="55" stroke="#edf1e6"/>${data.map(([name,value],i)=>{const share=value/total*345.575,part=`<circle cx="74" cy="74" r="55" stroke="${COLORS[i]}" stroke-dasharray="${share} ${345.575-share}" stroke-dashoffset="${-offset}"><title>${esc(name)}: ${esc(money(value))}</title></circle>`;offset+=share;return part;}).join('')}</svg><div class="donut-center"><strong>${money(total)}</strong><span>TOTAL SPENT</span></div></div><div class="category-legend">${data.map(([name,value],i)=>`<div class="category-line"><span class="legend-dot" style="background:${COLORS[i]}"></span><span>${esc(name)}</span><span class="percent">${Math.round(value/total*100)}%</span></div>`).join('')}</div></div>`;}
function transactionRow(t){const color=t.type==='income'?'':EXPENSE_CATEGORIES.indexOf(t.category)%3===0?'peach':EXPENSE_CATEGORIES.indexOf(t.category)%3===1?'purple':'';return `<button class="transaction-row" data-action="edit-transaction" data-id="${t.id}"><span class="transaction-icon ${color}">${icon(categoryIcon(t.category))}</span><span><span class="transaction-name">${esc(t.name)}</span><span class="transaction-meta" style="display:block">${esc(t.category)}</span></span><span class="transaction-end"><span class="transaction-amount ${t.type==='income'?'income':''}">${t.type==='income'?'+':'−'}${money(t.amountCents)}</span><span class="transaction-date" style="display:block">${shortDate(t.date)}</span></span></button>`;}
function goalCard(g,full=false){const percent=Math.min(100,Math.round(g.savedCents/g.targetCents*100));return `<article class="goal-card"><div class="goal-header"><span class="goal-symbol">${icon(g.name.toLowerCase().includes('trip')||g.name.toLowerCase().includes('getaway')?'plane':'goal')}</span><div><h3 class="goal-name">${esc(g.name)}</h3><p class="goal-date">${g.targetDate?'By '+shortDate(g.targetDate):'One step at a time'}</p></div>${full?`<button class="icon-button" style="margin-left:auto" data-action="edit-goal" data-id="${g.id}" aria-label="Edit ${esc(g.name)}">${icon('more')}</button>`:''}</div><div class="goal-progress-label"><strong>${money(g.savedCents)}</strong><span>${percent}% there</span></div><div class="progress" role="progressbar" aria-label="${esc(g.name)} savings progress" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%;background:${esc(g.color||COLORS[1])}"></span></div><p class="goal-amount">${g.savedCents>=g.targetCents?'You made it! Goal reached.':'of '+money(g.targetCents)+' · '+money(g.targetCents-g.savedCents)+' to go'}</p>${full?`<div class="goals-actions"><button class="btn btn-light btn-small" data-action="contribute" data-id="${g.id}">${icon('plus')}Add savings</button><span class="small-copy">Your future, a little closer.</span></div>`:''}</article>`;}
function renderOverview(){const transactions=state.transactions.filter(t=>t.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));return heading('Your money, a little clearer.','A little overview. A little peace of mind.','transaction','Add transaction',true)+demoBar()+summaryCards()+`<div class="chart-grid"><section class="panel"><div class="section-top"><div><h2>Money in, money out</h2><p class="small-copy">Your cumulative flow through the month.</p></div><div class="chart-legend"><span><i class="legend-dot"></i>Income</span><span><i class="legend-dot expense"></i>Expenses</span></div></div><div class="chart">${trendChart()}</div></section><section class="panel"><div class="section-top"><div><h2>Where it’s going</h2><p class="small-copy">A thoughtful look at your spending.</p></div><a class="text-link" href="#budgets">Budgets ${icon('arrow')}</a></div>${spendingChart()}</section></div><div class="bottom-grid"><section><div class="section-top"><div><h2>Recent activity</h2><p class="small-copy">The little things that add up.</p></div><a class="text-link" href="#transactions">View all ${icon('arrow')}</a></div>${transactions.length?`<div class="transaction-list">${transactions.slice(0,5).map(transactionRow).join('')}</div>`:empty('A fresh financial start.','Record your first income or expense and let the picture come together.')}</section><section><div class="section-top"><div><h2>Little goals. Big possibilities.</h2><p class="small-copy">Something good to work towards.</p></div><a class="text-link" href="#savings">All goals ${icon('arrow')}</a></div>${state.goals.length?`<div class="goal-preview">${state.goals.slice(0,2).map(g=>goalCard(g)).join('')}</div>`:empty('What’s on your horizon?','A trip, a rainy day fund, or something just for you.','goal','Set a savings goal','goal')}</section></div><aside class="tip">${icon('spark')}<p><strong>A little check-in goes a long way.</strong> Spend two minutes with your budget today. Your future self will thank you.</p></aside><p class="small-copy" style="margin-top:16px">Balance = recorded income minus expenses for ${esc(monthTitle())}. Savings and shared bills are separate records.</p>`;}
function renderTransactions(){let filtered=state.transactions.filter(t=>t.date.startsWith(month)&&(typeFilter==='all'||t.type===typeFilter)&&(categoryFilter==='All'||t.category===categoryFilter)&&(t.name+' '+t.category).toLowerCase().includes(search.toLowerCase()));filtered.sort((a,b)=>sort==='amount'?b.amountCents-a.amountCents:sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));return heading('Every little detail.','Track your everyday. Understand the bigger picture.','transaction','Add transaction',true)+demoBar()+`<div class="filter-bar"><div class="search-wrap">${icon('search')}<input id="transaction-search" class="input" aria-label="Search transactions" placeholder="Find a transaction…" value="${esc(search)}"></div><div class="tabs" role="group" aria-label="Transaction type">${[['all','All'],['expense','Money out'],['income','Money in']].map(([key,label])=>`<button class="${typeFilter===key?'active':''}" data-action="filter-type" data-value="${key}" aria-pressed="${typeFilter===key}">${label}</button>`).join('')}</div><select class="select" id="transaction-category" aria-label="Category filter">${['All',...new Set([...EXPENSE_CATEGORIES,...INCOME_CATEGORIES])].map(c=>`<option ${categoryFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="select" id="transaction-sort" aria-label="Sort transactions"><option value="newest" ${sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${sort==='oldest'?'selected':''}>Oldest first</option><option value="amount" ${sort==='amount'?'selected':''}>Largest amount</option></select></div><p class="result-count">${filtered.length} ${filtered.length===1?'transaction':'transactions'} · ${esc(monthTitle())}</p>${filtered.length?`<div class="transaction-list">${filtered.map(transactionRow).join('')}</div>`:empty('Nothing here just yet.','Try another filter or record something new.')}`;}
function renderBudgets(){const spend=categorySpend(state.transactions,month);return heading('A little room for everything.','Give your money a plan, without losing your freedom.','budget','Set a budget',true)+demoBar()+`<p class="result-count">Monthly limits repeat each month. Spending shown for ${esc(monthTitle())}.</p>${state.budgets.length?`<div class="budget-grid">${state.budgets.map(b=>{const used=Object.hasOwn(spend,b.category)?spend[b.category]:0,percent=Math.round(used/b.limitCents*100),left=b.limitCents-used;return `<article class="budget-card"><div class="budget-top"><div class="budget-name"><span class="transaction-icon">${icon(categoryIcon(b.category))}</span>${esc(b.category)}</div><button class="icon-button" data-action="edit-budget" data-id="${b.id}" aria-label="Edit ${esc(b.category)} budget">${icon('more')}</button></div><div class="budget-numbers"><strong>${money(used)}</strong><span>of ${money(b.limitCents)}</span></div><div class="progress ${left<0?'over':''}" role="progressbar" aria-label="${esc(b.category)} budget used" aria-valuenow="${Math.min(100,percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,percent)}%"></span></div><div class="budget-status ${left<0?'over':''}"><span>${left<0?money(-left)+' over':money(left)+' left'}</span><span>${percent}% used</span></div></article>`;}).join('')}</div>`:empty('Make a little plan.','Set a monthly limit for a category and see how your spending fits.','budget','Set your first budget','chart')}<aside class="tip">${icon('info')}<p>Budgets help you plan. They don’t restrict purchases or move money. Only recorded expenses count towards your limits.</p></aside>`;}
function renderSavings(){const total=state.goals.reduce((s,g)=>s+g.savedCents,0);return heading('Good things take a little saving.','Make room for the things that matter to you.','goal','New savings goal')+demoBar()+`<section class="savings-summary"><div><h2>A little closer to your dreams.</h2><p>${state.goals.length} ${state.goals.length===1?'goal':'goals'} to look forward to. Every contribution counts.</p></div><div><div class="savings-total">${money(total)}</div><p>Recorded across your savings goals</p></div></section>${state.goals.length?`<div class="savings-grid">${state.goals.map(g=>goalCard(g,true)).join('')}</div>`:empty('What would you love to save for?','Name your goal, set a target, and take it one small step at a time.','goal','Create a goal','goal')}<aside class="tip">${icon('info')}<p>Goals are your own savings records. Adding a contribution does not transfer money, create an expense, or change your recorded balance.</p></aside>`;}
function renderSplit(){const suggestion=settlements(state.bills,state.participants),net=balances(state.bills,state.participants);return heading('Good company. Fair shares.','A simple way to keep shared spending clear.','bill','Add shared bill')+demoBar()+`<div class="people">${state.participants.map(p=>`<span class="person-pill"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)}<button data-action="delete-person" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">${icon('close')}</button></span>`).join('')}<button class="person-add" data-action="person">${icon('plus')}Add a person</button></div><div class="split-grid"><section><div class="section-top"><div><h2>Shared little moments</h2><p class="small-copy">Bills are split equally, down to the last cent.</p></div></div>${state.bills.length?`<div class="bill-list">${state.bills.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<article class="bill-card"><span class="transaction-icon purple">${icon('split')}</span><div><h3 class="bill-title">${esc(b.title)}</h3><p class="bill-meta"><span>${esc(nameOf(b.paidBy))} paid</span><span>· ${b.participants.length} people</span><span>· ${shortDate(b.date)}</span></p></div><span class="bill-amount">${money(b.amountCents)}</span><div class="bill-actions"><button class="icon-button" data-action="edit-bill" data-id="${b.id}" aria-label="Edit ${esc(b.title)}">${icon('more')}</button></div></article>`).join('')}</div>`:empty('Let’s keep things fair.','Add the people in your group, then record a bill and who paid.','bill','Add your first bill','split')}</section><aside class="panel"><div class="section-top"><div><h2>A simpler way to settle up</h2><p class="small-copy">Suggested transfers across all shared bills.</p></div></div>${suggestion.length?suggestion.map(s=>`<div class="settlement"><span>${esc(nameOf(s.from))}</span>${icon('arrow')}<span>${esc(nameOf(s.to))}</span><strong>${money(s.amountCents)}</strong></div>`).join(''):`<div class="chart-empty">${icon('check')}<p style="margin-top:10px">${state.bills.length?'Everyone is even. Lovely.':'No balances to settle yet.'}</p></div>`}<p class="split-copy">These are suggestions based on the bills recorded here. No payments are sent. Shared bills are separate from personal transactions.</p>${state.participants.length?`<h3 style="font-size:11px;margin-top:24px">Group balances</h3>${state.participants.map(p=>`<div class="settlement"><span>${esc(p.name)}</span><strong class="${net[p.id]<0?'amount-negative':'amount-positive'}">${net[p.id]>0?'+':''}${money(net[p.id])}</strong></div>`).join('')}<p class="split-copy">Positive = to receive. Negative = to contribute.</p>`:''}</aside></div>`;}
function renderSettings(){const hasData=hasRealData();return heading('Make it feel like you.','A few little preferences for your everyday money.',null)+`<div class="settings-layout"><section class="settings-card"><h2>A buddy for every kind of budget.</h2><p>Choose what fits your life. Keep it simple.</p><div class="setting-row"><div><h3>Your profile</h3><p>One person, a family, or a shared home.</p></div><select id="profile-setting" class="select" aria-label="Budget profile">${['Individual','Student','Family','Roommates','Other'].map(p=>`<option ${state.profile===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="setting-row"><div><h3>Your currency</h3><p>Every record in a workspace uses one currency.</p></div><select id="currency-setting" class="select" aria-label="Workspace currency" ${hasData?'disabled':''}>${CURRENCIES.map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select></div>${hasData?'<p class="currency-warning">Currency changes do not convert amounts. Export your records, then start a fresh workspace to select a different currency.</p>':''}</section><section class="settings-card"><h2>Your data, close to home.</h2><p>${state.demo?'You’re exploring a sample budget. Start your own whenever you’re ready.':'Your entries are saved in this browser on this device.'}</p><div class="setting-actions"><button class="btn btn-outline" data-action="export">${icon('download')}Export backup</button><button class="btn btn-outline" data-action="import">${icon('download')}Import backup</button><button class="btn btn-light" data-action="sample">Explore sample budget</button><button class="btn btn-danger" data-action="fresh">Start fresh</button></div><p class="storage-note">${icon('info')}This first version keeps data on your device. Profiles and group members don’t create accounts or sync data between people. Browser data removal also removes your saved budget.</p></section><section class="settings-card"><h2>Keep the numbers meaningful.</h2><p>All money is entered manually and calculated in whole cents. This app does not connect to banks, send payments, or move savings. Shared bills and goals are tracked separately from personal transactions.</p></section></div>`;}
function hasRealData(){return !state.demo&&!!(state.transactions.length||state.bills.length||state.budgets.length||state.goals.length);}
function render(){if(!['overview','transactions','budgets','savings','split','settings'].includes(page))page='overview';shell();$('#main').innerHTML=(storageFailed?'<div class="storage-alert" role="alert">Changes stay in this session only. Device storage is unavailable. Export a backup before closing.</div>':'')+({overview:renderOverview,transactions:renderTransactions,budgets:renderBudgets,savings:renderSavings,split:renderSplit,settings:renderSettings}[page])();}
function go(target){if(page===target)render();else location.hash=target;}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();window.scrollTo(0,0);});
function dialog(title,body){$('#modal').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();}
function formError(message){const box=$('#form-error');if(box)box.textContent=message;else toast(message);}
function amountInput(name,value='',required=true){return `<div class="amount-field"><span>${state.currency}</span><input class="input" name="${name}" inputmode="decimal" type="text" placeholder="0.00" value="${esc(value)}" ${required?'required':''} autocomplete="off" maxlength="16"></div>`;}
function formActions(editId=null,deleteAction=''){return `<p id="form-error" class="form-error" role="alert"></p><div class="form-actions">${editId?`<button type="button" class="btn btn-danger" data-action="${deleteAction}" data-id="${editId}" aria-label="Delete record">${icon('trash')}</button>`:'<button type="button" class="btn btn-outline" data-action="close">Cancel</button>'}<button type="submit" class="btn btn-primary">${icon('check')}Save ${editId?'changes':'record'}</button></div>`;}
function freshDialog(next=''){dialog('A clear new beginning.',`<p class="dialog-copy">${state.demo?'Start your own empty budget. Example entries, budgets, goals, and bills will be removed.':'This clears the transactions, goals, budgets, people, and bills on this device. Export a backup first if you’d like to keep them.'}</p><label class="field"><span>Choose your currency</span><select id="fresh-currency" class="select">${CURRENCIES.map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select><small>This will not convert any existing records. It creates a new empty workspace.</small></label><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep exploring</button><button class="btn btn-primary" data-action="confirm-fresh" data-next="${next}">Start my budget ${icon('arrow')}</button></div>`);}
function ensureReal(next){if(state.demo){freshDialog(next);return false;}return true;}
function transactionDialog(t=null){dialog(t?'A little update.':'Let’s add a little detail.',`<form id="transaction-form" data-id="${t?.id||''}"><div class="form-row"><label class="field"><span>Type</span><select name="type" id="entry-type" class="select"><option value="expense" ${t?.type!=='income'?'selected':''}>Money out</option><option value="income" ${t?.type==='income'?'selected':''}>Money in</option></select></label><label class="field"><span>Amount</span>${amountInput('amount',t?decimal(t.amountCents):'')}</label></div><label class="field"><span>What was it for?</span><input name="name" class="input" placeholder="Coffee, payday, a little something…" maxlength="80" value="${esc(t?.name||'')}" required></label><div class="form-row"><label class="field"><span>Category</span><select name="category" id="entry-category" class="select">${(t?.type==='income'?INCOME_CATEGORIES:EXPENSE_CATEGORIES).map(c=>`<option ${t?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Date</span><input type="date" name="date" class="input" value="${t?.date||localDate()}" min="2000-01-01" max="2100-12-31" required></label></div>${formActions(t?.id,'delete-transaction')}</form>`);}
function budgetDialog(b=null){dialog(b?'A little room to adjust.':'Give your money a plan.',`<form id="budget-form" data-id="${b?.id||''}"><p class="dialog-copy">Choose a monthly spending limit. The same limit applies each month until you change it.</p><label class="field"><span>Category</span><select name="category" class="select">${EXPENSE_CATEGORIES.map(c=>`<option ${b?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Monthly limit</span>${amountInput('amount',b?decimal(b.limitCents):'')}</label>${formActions(b?.id,'delete-budget')}</form>`);}
function goalDialog(g=null){dialog(g?'A little goal update.':'Something to look forward to.',`<form id="goal-form" data-id="${g?.id||''}"><label class="field"><span>Give your goal a name</span><input name="name" class="input" maxlength="80" placeholder="A trip, a rainy day, a new beginning…" value="${esc(g?.name||'')}" required></label><div class="form-row"><label class="field"><span>Your target</span>${amountInput('target',g?decimal(g.targetCents):'')}</label><label class="field"><span>Already saved</span>${amountInput('saved',g?decimal(g.savedCents):'0.00')}</label></div><label class="field"><span>Target date (optional)</span><input name="targetDate" type="date" class="input" value="${g?.targetDate||''}" min="2000-01-01" max="2100-12-31"></label><p class="dialog-copy">A savings record, just for you. No money is moved or taken from your balance.</p>${formActions(g?.id,'delete-goal')}</form>`);}
function contributeDialog(g){dialog('A little closer.',`<div class="contribute-progress"><p>${esc(g.name)}</p><strong>${money(g.savedCents)} <span style="font-size:11px">of ${money(g.targetCents)}</span></strong></div><form id="contribute-form" data-id="${g.id}"><label class="field"><span>How much did you save?</span>${amountInput('amount')}</label><p class="dialog-copy">This updates your savings record. It does not move money or add an expense.</p>${formActions()}</form>`);}
function personDialog(){dialog('Who’s joining in?',`<form id="person-form"><label class="field"><span>Name</span><input name="name" class="input" maxlength="50" placeholder="You, a friend, a housemate…" required></label>${formActions()}</form>`);}
function billDialog(b=null){if(state.participants.length<2){dialog('Good company starts here.',`<p class="dialog-copy">Add at least two people to start splitting shared bills.</p><button class="btn btn-primary" data-action="person">${icon('plus')}Add a person</button>`);return;}dialog(b?'Let’s keep it clear.':'A little easier to share.',`<form id="bill-form" data-id="${b?.id||''}"><label class="field"><span>What did you share?</span><input name="title" class="input" maxlength="80" placeholder="Dinner, groceries, a weekend away…" value="${esc(b?.title||'')}" required></label><div class="form-row"><label class="field"><span>Total amount</span>${amountInput('amount',b?decimal(b.amountCents):'')}</label><label class="field"><span>Who paid?</span><select name="paidBy" class="select">${state.participants.map(p=>`<option value="${p.id}" ${b?.paidBy===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><label class="field"><span>Date</span><input name="date" type="date" class="input" value="${b?.date||localDate()}" min="2000-01-01" max="2100-12-31" required></label><span style="font-size:11px;font-weight:600;color:#7b926a">Split equally between</span><div class="checkboxes">${state.participants.map(p=>`<label class="checkbox-label"><input type="checkbox" name="participant" value="${p.id}" ${!b||b.participants.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div><p class="dialog-copy" style="margin-top:15px;margin-bottom:0">Any extra cent goes to the first selected person. This records a shared bill, not a payment.</p>${formActions(b?.id,'delete-bill')}</form>`);}
function remove(collection,entryId,label){const array=state[collection],index=array.findIndex(x=>x.id===entryId);if(index<0)return;const entry=array[index];array.splice(index,1);save();close();render();toast(`${label} removed.`,()=>{state[collection].splice(index,0,entry);save();render();toast('Record restored.');});}
function saveEntry(form){if(!form.reportValidity())return;const data=new FormData(form),existing=form.dataset.id,kind=form.id,previous=structuredClone(state);try{
 if(kind==='transaction-form'){const amountCents=toCents(data.get('amount'));if(amountCents<=0)throw Error('Please enter an amount greater than zero.');const entry={id:existing||id(),type:data.get('type'),name:data.get('name').trim(),amountCents,category:data.get('category'),date:data.get('date')};if(!entry.name)throw Error('Please add a name.');if(existing)state.transactions=state.transactions.map(t=>t.id===existing?entry:t);else state.transactions.push(entry);}
 else if(kind==='budget-form'){const limitCents=toCents(data.get('amount'));if(limitCents<=0)throw Error('Please set a limit greater than zero.');const category=data.get('category');if(state.budgets.some(b=>b.category===category&&b.id!==existing))throw Error('That category already has a budget. Edit its existing limit instead.');const entry={id:existing||id(),category,limitCents};if(existing)state.budgets=state.budgets.map(b=>b.id===existing?entry:b);else state.budgets.push(entry);}
 else if(kind==='goal-form'){const targetCents=toCents(data.get('target')),savedCents=toCents(data.get('saved'));if(targetCents<=0)throw Error('Please enter a target greater than zero.');const name=data.get('name').trim();if(!name)throw Error('Please give your goal a name.');const entry={id:existing||id(),name,targetCents,savedCents,targetDate:data.get('targetDate'),color:COLORS[1]};if(existing)state.goals=state.goals.map(g=>g.id===existing?entry:g);else state.goals.push(entry);}
 else if(kind==='contribute-form'){const amount=toCents(data.get('amount'));if(amount<=0)throw Error('Please enter a contribution greater than zero.');const g=state.goals.find(g=>g.id===existing);if(!Number.isSafeInteger(g.savedCents+amount))throw Error('That amount is too large.');g.savedCents+=amount;}
 else if(kind==='person-form'){const name=data.get('name').trim();if(!name)throw Error('Please enter a name.');if(state.participants.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('That person is already in your group.');state.participants.push({id:id(),name});}
 else if(kind==='bill-form'){const amountCents=toCents(data.get('amount')),participants=data.getAll('participant');if(amountCents<=0)throw Error('Please enter an amount greater than zero.');if(!participants.length)throw Error('Choose at least one person to share this bill.');const title=data.get('title').trim();if(!title)throw Error('Please give the bill a title.');const entry={id:existing||id(),title,amountCents,paidBy:data.get('paidBy'),participants,date:data.get('date')};if(existing)state.bills=state.bills.map(b=>b.id===existing?entry:b);else state.bills.push(entry);}
 state=validateImport(state);const persisted=save();close();render();toast(!persisted?'Changes are in this session only. Export a backup before closing.':kind==='contribute-form'?'A little closer to your goal.':kind==='person-form'?'Added to your group.':'Your record has been saved.');
 }catch(error){state=previous;formError(error.message||'Please check the details and try again.');}}
document.addEventListener('submit',event=>{if(['transaction-form','budget-form','goal-form','contribute-form','person-form','bill-form'].includes(event.target.id)){event.preventDefault();saveEntry(event.target);}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action,id:entryId,value}=button.dataset;
 if(action==='close')close();
 else if(action==='undo'){const fn=undoAction;undoAction=null;if(fn)fn();}
 else if(action==='settings'){close();go('settings');}
 else if(action==='transaction'){if(ensureReal('transaction'))transactionDialog();}
 else if(action==='budget'){if(ensureReal('budget'))budgetDialog();}
 else if(action==='goal'){if(ensureReal('goal'))goalDialog();}
 else if(action==='bill'){if(ensureReal('bill'))billDialog();}
 else if(action==='person'){if(ensureReal('person'))personDialog();}
 else if(action==='edit-transaction')transactionDialog(state.transactions.find(t=>t.id===entryId));
 else if(action==='edit-budget')budgetDialog(state.budgets.find(b=>b.id===entryId));
 else if(action==='edit-goal')goalDialog(state.goals.find(g=>g.id===entryId));
 else if(action==='edit-bill')billDialog(state.bills.find(b=>b.id===entryId));
 else if(action==='contribute')contributeDialog(state.goals.find(g=>g.id===entryId));
 else if(action==='delete-transaction')remove('transactions',entryId,'Transaction');
 else if(action==='delete-budget')remove('budgets',entryId,'Budget');
 else if(action==='delete-goal')remove('goals',entryId,'Goal');
 else if(action==='delete-bill')remove('bills',entryId,'Bill');
 else if(action==='delete-person'){if(state.bills.some(b=>b.paidBy===entryId||b.participants.includes(entryId)))toast('This person is part of a recorded bill. Remove those bills first.');else remove('participants',entryId,'Person');}
 else if(action==='filter-type'){typeFilter=value;render();}
 else if(action==='fresh')freshDialog();
 else if(action==='confirm-fresh'){const currency=$('#fresh-currency').value,profile=state.profile;clearUndo();state=freshState(false,currency,profile);save();close();render();const next=button.dataset.next;if(next==='transaction')transactionDialog();else if(next==='budget')budgetDialog();else if(next==='goal')goalDialog();else if(next==='bill')billDialog();else if(next==='person')personDialog();else toast('Your fresh budget is ready.');}
 else if(action==='sample'){dialog('Explore a sample budget?',`<p class="dialog-copy">This replaces the records on this device with examples. Export a backup first if you want to keep your own entries.</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep my budget</button><button class="btn btn-primary" data-action="confirm-sample">Explore sample</button></div>`);}
 else if(action==='confirm-sample'){clearUndo();state=freshState(true,state.currency,state.profile);month=currentMonth();save();close();go('overview');toast('You’re exploring example numbers.');}
 else if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`numiz-budget-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your budget backup has been exported.');}
 else if(action==='import'){$('#import-file').value='';$('#import-file').click();}
 else if(action==='confirm-import'){if(pendingImport){clearUndo();state=pendingImport;pendingImport=null;save();close();render();toast('Your budget backup is ready.');}}
});
let pendingImport=null;
document.addEventListener('change',async event=>{const el=event.target;
 if(el.id==='month-picker'){if(/^\d{4}-\d{2}$/.test(el.value)){month=el.value;render();}}
 else if(el.id==='transaction-category'){categoryFilter=el.value;render();}
 else if(el.id==='transaction-sort'){sort=el.value;render();}
 else if(el.id==='entry-type'){$('#entry-category').innerHTML=(el.value==='income'?INCOME_CATEGORIES:EXPENSE_CATEGORIES).map(c=>`<option>${esc(c)}</option>`).join('');}
 else if(el.id==='profile-setting'){state.profile=el.value;save();render();}
 else if(el.id==='currency-setting'){if(hasRealData()){render();return;}clearUndo();state.currency=el.value;save();render();toast('Currency updated for this empty workspace.');}
 else if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;if(file.size>2000000){toast('Please choose a JSON backup smaller than 2 MB.');return;}try{pendingImport=validateImport(JSON.parse(await file.text()));dialog('Bring your budget back.',`<p class="dialog-copy">This backup contains ${pendingImport.transactions.length} transactions, ${pendingImport.goals.length} goals, and ${pendingImport.bills.length} shared bills in ${pendingImport.currency}. Importing replaces the current workspace.</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep current budget</button><button class="btn btn-primary" data-action="confirm-import">Import backup</button></div>`);}catch(error){toast('This backup could not be imported: '+error.message);}}
});
document.addEventListener('input',event=>{if(event.target.id==='transaction-search'){const pos=event.target.selectionStart;search=event.target.value;render();$('#transaction-search').focus();$('#transaction-search').setSelectionRange(pos,pos);}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
save();render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
